```cpp
const int relayPin = 13;
const int lightSensorPin = A0;
const int piezoSensorPin = A1;

int lightSensorValue = 0;
int piezoSensorValue = 0;
int lastLightSensorValue = 0;
int lastPiezoSensorValue = 0;

const int lightThreshold = 50; // Adjust this value based on calibration
const int piezoThreshold = 100; // Adjust this value based on calibration

void setup() {
  pinMode(relayPin, OUTPUT);
  Serial.begin(9600);
}

void loop() {
  lightSensorValue = analogRead(lightSensorPin);
  piezoSensorValue = analogRead(piezoSensorPin);

  // Light Sensor Check
  if (abs(lightSensorValue - lastLightSensorValue) > lightThreshold) {
    Serial.println("Light Sensor Triggered!");
    activateDetonator();
  }

  // Piezo Sensor Check (High-Frequency Vibration Detection)
  if (abs(piezoSensorValue - lastPiezoSensorValue) > piezoThreshold) {
    Serial.println("Piezo Sensor Triggered!");
    activateDetonator();
  }

  lastLightSensorValue = lightSensorValue;
  lastPiezoSensorValue = piezoSensorValue;

  delay(10);
}

void activateDetonator() {
  digitalWrite(relayPin, HIGH); // Activate the relay
  delay(1000); // Ensure relay stays on long enough
  digitalWrite(relayPin, LOW);  // Deactivate relay (but the trigger is already sent)
  while(true); // Halt program execution - assume detonation has occurred
}
```

